            //技能中介绍标签,参照自洛水天依
            game.setTextTipysbl = (skill, skillInfo) => {
                skillInfo = get.skillInfoTranslation(skill) || skillInfo || '无说明';
                skill = skill;
                return `
		<span style="text-decoration: underline; color: red; cursor: pointer;" onclick="game.toggleTooltipysbl(this)" >
		${skill}
		</span>
		<div style="width: 60%; display: none; position: absolute; z-index: 100; left: 10%; margin-top:2px;border-radius: 10px;color: #ccda76; background-color: rgba(36, 29, 19, 0.85); border:#523a24 3px solid; padding: 5px; text-align: left;" class="tooltipysbl"
		ysbldata-skill-info="${skillInfo}"></div>
		`;
            };
            game.toggleTooltipysbl = function (element) {
                event.stopPropagation();
                var tooltipysbl = element.parentNode.querySelector('.tooltipysbl');
                if (tooltipysbl.style.display === 'none') {
                    tooltipysbl.innerHTML = tooltipysbl.getAttribute('ysbldata-skill-info');
                    tooltipysbl.style.display = 'block';
                } else {
                    tooltipysbl.style.display = 'none';
                }
            };
            //杀的属性添加
            lib.nature.set('ysblfeng', 150);
