            lib.translate['sha_nature_ysblfeng_info'] = '出牌阶段,对你攻击范围内的一名角色使用.其须使用一张【闪】,否则你对其造成1点伤害(风杀造成伤害后其弃置一张牌).';
            lib.inpile_nature.add('ysblfeng');
            //扩展ol明日方舟全局
            lib.element.player.ysblmrfz_hasCDSkill = function () {
                var player = this;
                var skills = player.getCards('s');
                for (var i = 0; i < skills.length; i++) {
                    var skill = skills[i];
                    if (lib.skill[skill] != undefined && lib.skill[skill].ysblmrfz_cd > 0) return true;
                }
                return false;
            };
            lib.element.player.ysblmrfz_coldDown = function () {
                var next = game.createEvent('ysblmrfz_coldDown');
                next.player = this;
                for (var i = 0; i < arguments.length; i++) {
                    if (typeof arguments[i] == 'string') {
                        next.skill = arguments[i];
                    }
                }
                var event = _status.event;
                next.source = event.player;
                next.setContent(lib.element.event.ysblmrfz_coldDown);
                return next;
            };
            lib.element.event.ysblmrfz_coldDown = function () {
                event.trigger('ysblmrfz_coldDown');
                if (player.ysblmrfz_hasCDSkill()) {
                    if (player.storage.ysblmrfz_cd_skill == undefined) player.storage.ysblmrfz_cd_skill = {};
                    if (skill != undefined) {
                        if (skill == 'all') {
                            var skills = player.getCards('s');
                            for (var i = 0; i < skills.length; i++) {
                                var skill = skills[i];
                                if (lib.skill[skill] != undefined && lib.skill[skill].ysblmrfz_cd > 0) player.storage.ysblmrfz_cd_skill[skill] = lib.skill[skill].ysblmrfz_cd;
                            }
                        } else {
                            player.storage.ysblmrfz_cd_skill[skill] = lib.skill[skill].ysblmrfz_cd;
                        }
                        player.markSkill('_ysblmrfz_cd_skill');
                    }
                }
            };
            lib.element.player.ysblmrfz_changeColdDown = function () {
                var next = game.createEvent('ysblmrfz_changeColdDown');
                next.player = this;
                for (var i = 0; i < arguments.length; i++) {
                    if (typeof arguments[i] == 'string') {
                        next.skill = arguments[i];
                    }
                    if (typeof arguments[i] == 'number') {
                        next.num = arguments[i];
                    }
                }
                var event = _status.event;
                next.source = event.player;
                next.setContent(lib.element.event.ysblmrfz_changeColdDown);
                return next;
            };
            lib.element.event.ysblmrfz_changeColdDown = function () {
                event.trigger('ysblmrfz_changeColdDown');
                if (num == undefined) num = -1;
                if (player.storage.ysblmrfz_cd_skill == undefined) player.storage.ysblmrfz_cd_skill = {};
                var storage = player.storage.ysblmrfz_cd_skill;
                if (skill != undefined) {
                    if (skill == 'all') {
                        for (var i in storage) {
                            player.storage.ysblmrfz_cd_skill[i] += num;
                            if (player.storage.ysblmrfz_cd_skill[i] < 0) player.storage.ysblmrfz_cd_skill[i] = 0;
                        }
                    } else {
                        if (storage[skill] == undefined) player.storage.ysblmrfz_cd_skill[skill] = 0;
                        player.storage.ysblmrfz_cd_skill[skill] += num;
                        if (player.storage.ysblmrfz_cd_skill[skill] < 0) player.storage.ysblmrfz_cd_skill[skill] = 0;
                    }
                    player.markSkill('_ysblmrfz_cd_skill');
                    var bool = false;
                    for (var i in player.storage.ysblmrfz_cd_skill) {
                        if (player.storage.ysblmrfz_cd_skill[i] > 0) bool = true;
                    }
                    //	if(bool==false||storage=={}) player.unmarkSkill('_ysblmrfz_cd_skill');
                }
            };
