                                if (name == 4 && filter({ name: 'sha', cards: [card], nature: 'fire' }, player, event)) return true;
                                if (name == 5 && filter({ name: 'wanjian', cards: [card] }, player, event)) return true;
                                if (name == 6 && filter({ name: 'juedou', cards: [card] }, player, event)) return true;
